&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;51fmt-0-0&quot;&gt;&lt;span data-offset-key=&quot;51fmt-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Background working closely with or embedded within a RevOps function&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
