&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;46j1j-0-0&quot;&gt;&lt;span data-offset-key=&quot;46j1j-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Must be located in the Washington DC Metro area&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
