&lt;ul class=&quot;public-DraftStyleDefault-ul&quot; data-offset-key=&quot;67h5l-0-0&quot;&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;3gb59&quot; data-offset-key=&quot;67h5l-0-0&quot;&gt;
