&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;3gb59&quot; data-offset-key=&quot;fn9h4-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;fn9h4-0-0&quot;&gt;&lt;span data-offset-key=&quot;fn9h4-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Prior experience in a technical training, instruction, or curriculum development capacity is a plus&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
