&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; style=&quot;text-align: justify;&quot; data-block=&quot;true&quot; data-editor=&quot;f4nlt&quot; data-offset-key=&quot;bhu8d-0-0&quot;&gt;
