&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;f4nlt&quot; data-offset-key=&quot;drmbk-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; style=&quot;text-align: justify;&quot; data-offset-key=&quot;drmbk-0-0&quot;&gt;&lt;span data-offset-key=&quot;drmbk-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Identify and champion improvements to security, stability, and cost efficiency before they become problems.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;What You Bring :&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;f4nlt&quot; data-offset-key=&quot;8li0g-0-0&quot;&gt;
