&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;f4nlt&quot; data-offset-key=&quot;f0hkk-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;f0hkk-0-0&quot;&gt;&lt;span data-offset-key=&quot;f0hkk-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;You can work autonomously, drive decisions and results in a distributed team by leveraging asynchronous, direct, and transparent communication.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;f4nlt&quot; data-offset-key=&quot;b0f1v-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;b0f1v-0-0&quot;&gt;&lt;span data-offset-key=&quot;b0f1v-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;You communicate clearly and can influence direction across teams and levels without formal authority.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Bonus Points :&lt;/strong&gt;&lt;/h3&gt;
&lt;ul class=&quot;public-DraftStyleDefault-ul&quot; data-offset-key=&quot;c3icl-0-0&quot;&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;f4nlt&quot; data-offset-key=&quot;c3icl-0-0&quot;&gt;
