&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;96g3r-0-0&quot;&gt;&lt;span data-offset-key=&quot;96g3r-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;You have worked with Kubernetes operators or Elastic Cloud on Kubernetes (ECK).&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
