&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;6nedj-0-0&quot;&gt;&lt;span data-offset-key=&quot;6nedj-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Experience with data storage technology.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
