&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;1udp0&quot; data-offset-key=&quot;74ged-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;74ged-0-0&quot;&gt;&lt;span data-offset-key=&quot;74ged-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;AI Tooling: Daily proficiency using AI-assisted coding tools to accelerate scaffolding, refactoring, and debugging.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;1udp0&quot; data-offset-key=&quot;2sg13-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;2sg13-0-0&quot;&gt;&lt;span data-offset-key=&quot;2sg13-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Architecture &amp;amp; Delivery: Solid knowledge of software design patterns, SDLC, sandbox lifecycle management, and metadata deployment mechanics.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;1udp0&quot; data-offset-key=&quot;a825k-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;a825k-0-0&quot;&gt;&lt;span data-offset-key=&quot;a825k-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Education: Bachelor&#39;s degree in Computer Science, Engineering, Information Systems, or related field.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
